// Actual binary digits of pi, certified at runtime with integer arithmetic.
// This is source for the user's native compiler. No digits are generated by
// an authoring-side compiler, renderer, numerical script or bundled table.
//
// The exact identity is pi = 16 atan(1/5) - 4 atan(1/239). With S=2^P,
// the alternating series term S/((2k+1) q^(2k+1)) has floor
//   floor(floor(S/q^(2k+1))/(2k+1)).
// Repeated division by q^2 computes the inner floor EXACTLY. Each term is
// enclosed by [floor, floor+1], accumulated with its alternating sign.
// At the first zero inner floor, the alternating-series tail has the next
// sign and magnitude <1 in fixed-point units. Directed Machin combination
// then encloses S*pi between unsigned integer endpoints L and U.
//
// Certification requires floor(L/2^(P-4095)) == floor(U/2^(P-4095)).
// Both endpoints, and hence pi, then have exactly the same integer part
// and first 4095 fractional bits. A failed comparison throws; it NEVER
// supplies approximate digits. P=4352 includes 257 guard bits, but the
// actual endpoint comparison, not that guard-bit count, is the certificate.
namespace project_pi {
inline constexpr std::size_t bitCount=4096;
inline constexpr unsigned certifiedThrough=4095;

namespace detail {
inline constexpr unsigned fractionBits=4352;

// A minimal nonnegative integer, little-endian in base 2^32. All products
// and division numerators use uint64_t; there are no floating-point steps.
class UInt {
    std::vector<std::uint32_t> word_;

    void normalize() {
        while (word_.size()>1 && word_.back()==0) word_.pop_back();
    }

public:
    explicit UInt(std::uint32_t value=0):word_(1,value) {}

    static UInt powerOfTwo(unsigned exponent) {
        UInt value;
        value.word_.assign(std::size_t(exponent/32)+1,0);
        value.word_[exponent/32]=std::uint32_t(1)<<(exponent%32);
        return value;
    }

    bool zero() const { return word_.size()==1 && word_[0]==0; }

    int compare(const UInt& other) const {
        if (word_.size()!=other.word_.size())
            return word_.size()<other.word_.size() ? -1 : 1;
        for (std::size_t i=word_.size();i-- >0;)
            if (word_[i]!=other.word_[i])
                return word_[i]<other.word_[i] ? -1 : 1;
        return 0;
    }

    void add(const UInt& other) {
        const std::size_t count=std::max(word_.size(),other.word_.size());
        word_.resize(count,0);
        std::uint64_t carry=0;
        for (std::size_t i=0;i<count;++i) {
            const std::uint64_t sum=std::uint64_t(word_[i])+carry+
                (i<other.word_.size() ? other.word_[i] : 0);
            word_[i]=std::uint32_t(sum);
            carry=sum>>32;
        }
        if (carry) word_.push_back(std::uint32_t(carry));
    }

    void addSmall(std::uint32_t value) {
        std::uint64_t carry=value;
        for (std::size_t i=0;i<word_.size() && carry;++i) {
            const std::uint64_t sum=std::uint64_t(word_[i])+carry;
            word_[i]=std::uint32_t(sum);
            carry=sum>>32;
        }
        if (carry) word_.push_back(std::uint32_t(carry));
    }

    void subtract(const UInt& other) {
        if (compare(other)<0)
            throw std::runtime_error("Pi interval integer underflow");
        std::uint64_t borrow=0;
        for (std::size_t i=0;i<word_.size();++i) {
            const std::uint64_t right=borrow+
                (i<other.word_.size() ? std::uint64_t(other.word_[i]) : 0);
            const std::uint64_t left=word_[i];
            word_[i]=std::uint32_t(left-right);
            borrow=left<right ? 1 : 0;
        }
        normalize();
    }

    void subtractSmall(std::uint32_t value) { subtract(UInt(value)); }

    void multiplySmall(std::uint32_t factor) {
        std::uint64_t carry=0;
        for (std::uint32_t& word:word_) {
            const std::uint64_t product=std::uint64_t(word)*factor+carry;
            word=std::uint32_t(product);
            carry=product>>32;
        }
        if (carry) word_.push_back(std::uint32_t(carry));
        normalize();
    }

    std::uint32_t divideSmall(std::uint32_t divisor) {
        if (!divisor) throw std::runtime_error("Pi interval zero divisor");
        std::uint64_t remainder=0;
        for (std::size_t i=word_.size();i-- >0;) {
            const std::uint64_t numerator=(remainder<<32)|word_[i];
            word_[i]=std::uint32_t(numerator/divisor);
            remainder=numerator%divisor;
        }
        normalize();
        return std::uint32_t(remainder);
    }

    UInt shiftedRight(unsigned count) const {
        const std::size_t whole=count/32;
        const unsigned part=count%32;
        if (whole>=word_.size()) return UInt();
        UInt result;
        result.word_.resize(word_.size()-whole);
        for (std::size_t i=0;i<result.word_.size();++i) {
            result.word_[i]=word_[i+whole]>>part;
            if (part && i+whole+1<word_.size())
                result.word_[i]|=word_[i+whole+1]<<(32-part);
        }
        result.normalize();
        return result;
    }

    int bit(unsigned index) const {
        const std::size_t whole=index/32;
        return whole<word_.size() ? int((word_[whole]>>(index%32))&1u) : 0;
    }
};

struct Interval {
    UInt lower,upper;
    std::size_t terms=0;
};

// Only q=5 and q=239 are used. Every stored lower partial sum is positive:
// each negative term follows a larger positive term, and the first term
// dominates the few thousand one-unit rounding allowances by many orders.
inline Interval atanInverse(std::uint32_t q) {
    if (q!=5 && q!=239)
        throw std::invalid_argument("Pi interval unsupported Machin denominator");
    UInt power=UInt::powerOfTwo(fractionBits);
    power.divideSmall(q);
    Interval result;
    std::uint32_t odd=1;
    bool positive=true;
    while (!power.zero()) {
        UInt term=power;
        term.divideSmall(odd);
        if (positive) {
            result.lower.add(term);
            result.upper.add(term);
            result.upper.addSmall(1);
        } else {
            result.lower.subtract(term);
            result.lower.subtractSmall(1);
            result.upper.subtract(term);
        }
        ++result.terms;
        power.divideSmall(q*q);
        odd+=2;
        positive=!positive;
    }
    // Exact next term is below one fixed-point unit; the entire remaining
    // alternating tail lies between zero and that signed next term.
    if (positive) result.upper.addSmall(1);
    else result.lower.subtractSmall(1);
    return result;
}

struct Prefix {
    UInt lower,upper;
    std::vector<int> digits;
    std::size_t terms5=0,terms239=0;
};

inline bool matchingPrefix(const Prefix& prefix) {
    constexpr unsigned shift=fractionBits-certifiedThrough;
    return prefix.lower.shiftedRight(shift).compare(
               prefix.upper.shiftedRight(shift))==0;
}

inline Prefix makePrefix() {
    const Interval a=atanInverse(5),b=atanInverse(239);
    Prefix prefix;
    prefix.lower=a.lower;
    prefix.lower.multiplySmall(16);
    UInt negative=b.upper;
    negative.multiplySmall(4);
    prefix.lower.subtract(negative);
    prefix.upper=a.upper;
    prefix.upper.multiplySmall(16);
    negative=b.lower;
    negative.multiplySmall(4);
    prefix.upper.subtract(negative);
    if (prefix.lower.compare(prefix.upper)>0 || !matchingPrefix(prefix))
        throw std::runtime_error("Pi binary prefix enclosure did not certify 4095 fractional bits");
    prefix.digits.resize(bitCount);
    for (std::size_t n=0;n<bitCount;++n)
        prefix.digits[n]=prefix.lower.bit(fractionBits-unsigned(n));
    prefix.terms5=a.terms;
    prefix.terms239=b.terms;
    return prefix;
}

inline const Prefix& cache() {
    // C++11 and later guarantee thread-safe initialization. Only a fully
    // certified cache is published; an exception cannot expose partial data.
    static const Prefix prefix=makePrefix();
    return prefix;
}
} // namespace detail

// beta_n = floor(2^n*pi) mod 2. Index 0 is the units bit (1), and indices
// 1..4095 are fractional bits. The prefix is finite, exact, and independent
// of any statistical assertion concerning pi's infinite digit sequence.
inline const std::vector<int>& bits() { return detail::cache().digits; }
inline int actualPiBit(std::size_t n) { return bits().at(n); }
inline bool certified() { return detail::matchingPrefix(detail::cache()); }

// Stable floating-point evaluation of the analytic drift. Unlike the bit
// prefix, this coefficient is not enclosed by exact integer arithmetic.
inline double drift(int x) {
    if (x<1) throw std::invalid_argument("Pi drift requires x >= 1");
    const double value=double(x);
    return std::log1p(1.0/(value*(value+2.0)))/
           (2.0*std::log1p(2.0/value));
}

// Optional native self-test SOURCE; not executed during package authoring.
// The familiar hexadecimal prefix is only a cross-check. Full-length digit
// certification comes from the independently computed interval endpoints.
inline int selfTest(std::ostream& out) {
    int checks=0;
    auto require=[&](bool condition,const char* name) {
        ++checks;
        if (!condition) {
            out << "PROJECT_PI_CHECK_FAIL=" << name << '\n';
            throw std::runtime_error(std::string("Pi digit self-test: ")+name);
        }
    };
    const detail::Prefix& prefix=detail::cache();
    require(prefix.digits.size()==bitCount,"digit_count");
    require(detail::matchingPrefix(prefix),"full_prefix_integer_enclosure");
    require(prefix.lower.shiftedRight(detail::fractionBits).compare(detail::UInt(3))==0 &&
            prefix.upper.shiftedRight(detail::fractionBits).compare(detail::UInt(3))==0,
            "integer_part_three");
    require(actualPiBit(0)==1,"units_bit");
    std::uint32_t first=0;
    for (std::size_t n=1;n<=32;++n) first=(first<<1)|std::uint32_t(actualPiBit(n));
    require(first==UINT32_C(0x243f6a88),"known_first_32_fractional_bits");
    out << "PROJECT_PI_CERTIFIED_FRACTIONAL_BITS=" << certifiedThrough << '\n';
    out << "PROJECT_PI_MACHIN_TERMS=" << prefix.terms5 << ',' << prefix.terms239 << '\n';
    return checks;
}
} // namespace project_pi
